local m=peripheral.find("monitor")
local d=m or term.current()
if m then m.setTextScale(0.5) end
d.clear()
local tw,th=d.getSize()

local staticText=string.rep(" ", tw)
local staticTC=string.rep("0", tw)
local delay=1/fps
local nextFrame=os.clock()+delay

local function drawRow(y, colorRow)
 local len=math.min(#colorRow, tw)
 if y<=th and len>0 then
  d.setCursorPos(1, y)
  d.blit(staticText:sub(1, len), staticTC:sub(1, len), colorRow:sub(1, len))
 end
end

for _,frame in ipairs(frames) do
 if frame.t=="F" then
  for y, row in ipairs(frame.d) do
   drawRow(y, row)
  end
 else
  for _, change in ipairs(frame.d) do
   drawRow(change[1], change[2])
  end
 end
 local now=os.clock()
 if now<nextFrame then sleep(nextFrame-now) end
 nextFrame=os.clock()+delay
end
d.clear()
d.setCursorPos(1,1)
print("Done")
